const documentApi: IApiPlugin = {
  origin: "https://docspace.example.com",
  proxy: "/api/proxy",
  prefix: "/api/v1",

  setOrigin(origin) {
    try {
      this.origin = origin;
      return {
        actions: [Actions.showToast],
        toastProps: [{
          type: "success",
          title: "Origin Updated",
          message: "API endpoint changed | Config saved | Ready to use"
        }]
      };
    } catch (error) {
      return {
        actions: [Actions.showToast],
        toastProps: [{
          type: "error",
          title: "Update Failed",
          message: "Unable to update origin | Check URL format"
        }]
      };
    }
  },

  setProxy(proxy) {
    this.proxy = proxy;
  },

  setPrefix(prefix) {
    this.prefix = prefix;
  },

  getOrigin() {
    return this.origin;
  },

  getProxy() {
    return this.proxy;
  },

  getPrefix() {
    return this.prefix;
  },

  setAPI(origin, proxy, prefix) {
    try {
      this.origin = origin;
      this.proxy = proxy;
      this.prefix = prefix;
      return {
        actions: [Actions.showToast],
        toastProps: [{
          type: "success",
          title: "API Updated",
          message: "Configuration saved | Endpoints updated | Ready to use"
        }]
      };
    } catch (error) {
      return {
        actions: [Actions.showToast],
        toastProps: [{
          type: "error",
          title: "Update Failed",
          message: "Unable to update API | Check configuration"
        }]
      };
    }
  },

  getAPI() {
    return {
      origin: this.origin,
      proxy: this.proxy,
      prefix: this.prefix
    };
  }
};
